manipulate-scene.sql-solution:
DELETE FROM passengers
WHERE name IN (
SELECT b.name
FROM bus_station b
);

select-scene.sql-solution:
SELECT *
FROM luggage
WHERE passenger_id NOT IN (
    SELECT passenger_id
    FROM check_ins
);

game.initial-sql-script:
CREATE TABLE passengers ( passenger_id INT, name VARCHAR(100), passport_no VARCHAR(50), nationality VARCHAR(50) );
CREATE TABLE check_ins ( checkin_id INT, passenger_id INT, seat_number VARCHAR(10) );
CREATE TABLE bus_station ( person_id INT, name VARCHAR(100), location VARCHAR(50) );
CREATE TABLE sunglasses ( sunglasses VARCHAR(100), passenger_id INT );
CREATE TABLE seats ( seat_number VARCHAR(10), position VARCHAR(20) );
CREATE TABLE luggage ( luggage_id INT PRIMARY KEY, passenger_id INT, weight_kg DECIMAL(5,2) );
CREATE TABLE crew ( crew_id INT PRIMARY KEY, name VARCHAR(50), role VARCHAR(50) );
CREATE TABLE duty_assignments ( assignment_id INT PRIMARY KEY, crew_id INT, duty VARCHAR(100) );
CREATE TABLE meal_options ( meal_id INT PRIMARY KEY, meal_name VARCHAR(100), category VARCHAR(50) );
CREATE TABLE meal_orders ( order_id INT PRIMARY KEY, passenger_id INT, meal_id INT );
